<template>
  <main class="event-shell">
    <header v-if="race" class="hero">
      <img class="hero-photo" :src="heroUrl" :alt="archive?.hero?.alt || race.name + '赛事封面'" @error="heroFailed=true" />
      <div class="hero-shade"></div>
      <div class="hero-top"><router-link :to="directoryTo" aria-label="返回赛事档案目录">‹</router-link><span>赛事档案</span><span v-if="!archive?.hero?.imageUrl || heroFailed" class="hero-photo-label">原创插画</span></div>
      <div class="hero-copy"><div class="hero-eyebrow">{{ race.city }} · MARATHON</div><h1>{{ race.name }}<span>{{ race.tagline }}</span></h1><div class="hero-tags"><span>42.195 km</span><span v-if="race.worldAthletics?.label">世界田联 {{ certification(race.worldAthletics) }}</span><span v-if="race.caa?.label">中国田协 {{ certification(race.caa) }}</span></div></div>
    </header>
    <div v-if="loading" class="archive-state">正在加载赛事档案…</div>
    <div v-else-if="error" class="archive-state" role="alert">{{ error }} <button type="button" @click="load">重新加载</button></div>
    <template v-else-if="race && archive">
      <nav class="main-tabs" aria-label="赛事栏目"><button v-for="item in tabs" :key="item.id" type="button" :aria-selected="tab===item.id" @click="setTab(item.id)">{{ item.label }}</button></nav>
      <div class="page-content">
        <router-link v-if="fromRace" class="return-link" :to="'/races/'+fromRace.id">‹ 返回 {{ fromRace.name }} 报名信息</router-link>
        <template v-if="tab==='overview'">
          <div class="section-head"><div><p class="eyebrow">ABOUT THE RACE</p><h2>关于{{ race.shortName || race.name }}</h2></div></div>
          <p class="intro-text">{{ archive.intro || race.summary || race.tagline }}</p>
          <div class="identity-facts"><div><b>{{ foundingYear }}</b><span>创办年份</span></div><div><b>42.195</b><span>全程公里</span></div><div><b>{{ race.city }}</b><span>举办城市</span></div></div>
          <div v-if="latest" class="latest-strip"><div><h3>最近收录 · {{ latest.year }}</h3><p>{{ latest.participation?.planned || latest.distance || '全程马拉松' }}</p></div><div class="date">{{ latest.date || latest.year }}</div></div>
          <div class="feature-layout"><button class="feature" type="button" @click="setTab('route')"><p class="eyebrow">THE COURSE</p><h3>一条赛道，<br>一座城市的记忆。</h3><p>{{ latest?.route?.start || '起点待录入' }} → {{ latest?.route?.finish || '终点待录入' }}</p><span class="feature-mark" aria-hidden="true">42.195</span><span class="feature-bottom">探索赛道变化 <span class="mini-arrow">↗</span></span></button><div class="story-rows"><button v-for="(item,index) in (archive.highlights||[]).slice(0,2)" :key="index" class="story-row" type="button" @click="openReader(item)"><span class="num">0{{ index+1 }}</span><span><h3>{{ item.title }}</h3><p>{{ item.body }}</p></span></button></div></div>
          <section class="section"><div class="section-head"><div><p class="eyebrow">THE COLLECTION</p><h2>留下的，不止成绩</h2></div><button class="tiny-link" @click="setTab('gallery')">进入图鉴 →</button></div><div class="category-tiles"><button v-for="g in galleryTypes.slice(0,3)" :key="g.id" class="category-tile" type="button" @click="gallery=g.id;setTab('gallery')"><span class="tile-mark">{{ g.mark }}</span><h3>{{ g.label }}</h3><p>按年份浏览 →</p></button></div></section>
        </template>
        <template v-if="tab==='entry'">
          <div class="section-head"><div><p class="eyebrow">RACE DAY</p><h2>参赛与报名</h2></div><select v-model="entryYear" class="select-year" aria-label="选择参赛年份"><option v-for="y in years" :key="y" :value="y">{{ y }} 年</option></select></div>
          <div class="subnav"><button v-for="i in entryTypes" :key="i.id" type="button" :aria-pressed="entryType===i.id" @click="entryType=i.id">{{ i.label }}</button></div>
          <template v-if="currentEntry && entryType==='registration'"><h3 class="minor-heading">{{ entryYear }} 报名安排</h3><p class="muted" style="margin-top:14px">{{ currentEntry.registration?.method }}</p><div class="timeline"><div><small>报名开始</small><strong>{{ currentEntry.registration?.opens || '未录入' }}</strong></div><div><small>报名截止</small><strong>{{ currentEntry.registration?.closes || '未录入' }}</strong></div><div><small>抽签公布</small><strong>{{ currentEntry.registration?.drawDate || '未录入' }}</strong></div></div><div class="facts"><div v-for="f in facts(currentEntry.registration,registrationFields)" :key="f.label" class="fact"><span>{{ f.label }}</span><span>{{ f.value }}</span></div></div><p v-if="currentEntry.registration?.note" class="muted" style="margin-top:18px">{{ currentEntry.registration.note }}</p><div class="comparison"><h3>历年报名与中签</h3><div class="compare-head"><span>年份</span><span>报名人数</span><span>公布中签率</span></div><div v-for="e in editions" :key="e.year" class="compare-row"><span class="year">{{ e.year }}</span><span><b>{{ e.registration?.applicants || '—' }}</b></span><span><b>{{ e.registration?.lotteryRate || '—' }}</b></span></div></div><p v-if="currentEntry.registration?.lotteryNote" class="callout">{{ currentEntry.registration.lotteryNote }}</p></template>
          <template v-else-if="currentEntry"><div v-for="group in guideGroups" :key="group.title" class="section"><h3 class="minor-heading">{{ group.title }}</h3><div class="facts"><div v-for="f in group.fields" :key="f.label" class="fact"><span>{{ f.label }}</span><span>{{ f.value }}</span></div></div></div><div v-if="!guideGroups.length" class="empty"><h3>参赛指南暂未录入</h3></div></template>
          <div v-else class="empty"><h3>参赛资料暂未录入</h3></div>
        </template>
        <template v-if="tab==='route'"><div class="section-head"><div><p class="eyebrow">THE COURSE</p><h2>赛道与变化</h2></div></div><div v-if="routeEdition" class="route-layout"><div class="route-visual"><div><p class="eyebrow">{{ routeEdition.year }} · 赛道</p><ol class="road-order"><li v-for="(stage,index) in routeStages" :key="index"><span class="dot"></span>{{ stage }}</li></ol></div><span class="route-watermark" aria-hidden="true">42.195</span><small>道路顺序示意，不代表精确轨迹。</small></div><div><p class="eyebrow">赛道版本</p><div class="versions"><button v-for="e in routeVersions" :key="e.id" class="version-card" type="button" :aria-pressed="e.years.includes(routeYear)" @click="routeYear=e.years[0]"><b>{{ e.title }}</b><span>{{ e.note || e.route?.changes }}</span><em v-for="y in e.years" :key="y">{{ y }}</em></button></div><p class="version-caption">{{ activeRouteGroup?.match==='similar'?'道路序列相近，细部轨迹分别保留。':'按后台维护的路线版本归档。' }}</p><select v-if="activeRouteGroup?.years.length>1" v-model="routeYear" class="select-year" aria-label="选择版本内年份"><option v-for="y in activeRouteGroup.years" :key="y" :value="y">{{ y }} 年</option></select></div></div><div v-if="routeEdition" class="route-insights"><div><h3>路线变化</h3><p>{{ routeEdition.route?.changes || '暂未录入路线变化。' }}</p></div><div><h3>跑法参考</h3><p v-for="(line,i) in routeEdition.route?.analysis || []" :key="i">{{ line }}</p></div></div><div v-if="routeEdition?.route?.mapUrl" class="section"><img class="course-image" :src="routeEdition.route.mapUrl" :alt="routeYear+' 年赛道图'" /></div><div v-if="!routeEdition" class="empty"><h3>赛道资料暂未录入</h3></div></template>
        <template v-if="tab==='results'"><div class="section-head"><div><p class="eyebrow">THE RESULTS</p><h2>成绩与完赛</h2></div><select v-model="resultsYear" class="select-year" aria-label="选择成绩年份"><option v-for="y in years" :key="y" :value="y">{{ y }} 年</option></select></div><div v-if="resultEdition"><div class="champion-grid"><article v-for="(result,i) in (resultEdition.results||[]).slice(0,2)" :key="i" class="champion"><small>{{ result.group }}</small><div class="rank">01</div><div class="time">{{ result.time }}</div><div class="name">{{ result.athlete }}</div><div class="timing">{{ result.timing || '计时口径待录入' }}</div></article></div><div v-if="!resultEdition.results?.length" class="empty"><h3>本届成绩暂未录入</h3></div><div v-for="(result,i) in (resultEdition.results||[]).slice(2)" :key="i" class="result-row"><div><h3>{{ result.group }}</h3><span>{{ result.athlete }}</span></div><b>{{ result.time }}</b></div><section class="section"><h3 class="minor-heading">参赛与完赛</h3><div class="facts"><div v-for="f in facts(resultEdition.participation,participationFields)" :key="f.label" class="fact"><span>{{ f.label }}</span><span>{{ f.value }}</span></div></div><p v-if="resultEdition.participation?.note" class="callout">{{ resultEdition.participation.note }}</p></section></div><div v-else class="empty"><h3>成绩暂未录入</h3></div></template>
        <template v-if="tab==='gallery'"><div class="section-head"><div><p class="eyebrow">THE COLLECTION</p><h2>赛事图鉴</h2></div></div><div class="subnav"><button v-for="g in galleryTypes" :key="g.id" type="button" :aria-pressed="gallery===g.id" @click="gallery=g.id">{{ g.label }}</button></div><div class="gallery-intro"><p>一件件收藏，留下每一年的记忆。</p></div><template v-if="gallery!=='albums'"><article v-for="item in galleryEntries" :key="item.year" class="collection-year"><div class="collection-head"><b>{{ item.year }}</b><span>{{ item.gear.name || item.gear.category }}</span></div><div v-if="item.images.length" class="photo-group"><button v-for="(img,i) in item.images" :key="i" class="gallery-picture" type="button" @click="openImage(img,item.gear.name,item.images,i)"><img :src="img.url" :alt="img.caption || item.gear.name" loading="lazy"/><span v-if="img.caption">{{ img.caption }}</span></button></div><div class="collection-copy"><p>{{ item.gear.description }}</p><div v-if="item.gear.items?.length" class="pills"><span v-for="p in item.gear.items" :key="p">{{ p }}</span></div></div></article><div v-if="!galleryEntries.length" class="empty"><h3>内容暂未录入</h3></div></template><template v-else><div v-if="albums.length" class="album-layout"><button v-for="album in albums" :key="album.id" class="album-card" type="button" @click="openAlbum(album)"><img v-if="album.media?.[0]?.url" :src="album.media[0].url" :alt="album.title" /><div><strong>{{ album.year }} · {{ album.title }}</strong><span>{{ album.media?.length || 0 }} 张照片</span></div></button></div><div v-else class="empty"><h3>年度相册暂未录入</h3><p>有照片后，这里会按年份呈现。</p></div></template></template>
        <template v-if="tab==='updates'"><div class="section-head"><div><p class="eyebrow">STORIES & NEWS</p><h2>{{ race.shortName || race.name }}动态</h2></div></div><div class="subnav"><button type="button" :aria-pressed="updatesType==='stories'" @click="updatesType='stories'">新鲜事</button><button type="button" :aria-pressed="updatesType==='news'" @click="updatesType='news'">相关新闻</button></div><div v-if="updatesType==='stories'" class="story-grid"><button v-for="(item,i) in stories" :key="i" class="story-card" type="button" @click="openReader(item)"><div class="story-art" :class="{red:i%2}"><img v-if="item.images?.[0]?.url" :src="item.images[0].url" :alt="item.title"/><span v-else>{{ item.editionYear || String(i+1).padStart(2,'0') }}</span><small>{{ item.tag || '赛事记忆' }}</small></div><div class="text"><small>{{ item.tag || '赛事故事' }} <template v-if="item.editionYear">· {{ item.editionYear }}</template></small><h3>{{ item.title }}</h3><p>{{ item.summary || item.body }}</p></div></button></div><template v-else><button v-for="(item,i) in news" :key="i" class="news-row" type="button" @click="openReader(item)"><span class="news-date"><b>{{ (item.publishedAt||'').slice(5) || '—' }}</b>{{ (item.publishedAt||'').slice(0,4) }}</span><span><span class="news-tag">{{ item.tag || '赛事新闻' }}</span><h3>{{ item.title }}</h3><p>{{ item.summary }}</p></span><span class="arrow">↗</span></button></template><div v-if="(updatesType==='stories'&&!stories.length)||(updatesType==='news'&&!news.length)" class="empty"><h3>内容暂未录入</h3></div></template>
      </div>
      <footer><strong>把一场比赛，慢慢读懂。</strong><span>赛事档案 · {{ race.city }}</span></footer>
      <dialog ref="reader" @click.self="closeReader" @keydown.left.prevent="changeImage(-1)" @keydown.right.prevent="changeImage(1)"><button class="dialog-close" type="button" aria-label="关闭" @click="closeReader">×</button><div v-if="reading" class="dialog-content"><p class="eyebrow">{{ reading.tag || '赛事档案' }}</p><h2>{{ reading.title }}</h2><img v-if="reading.image" :src="reading.image" :alt="reading.caption || reading.title" /><p style="white-space:pre-line">{{ reading.body || reading.summary }}</p><p v-if="reading.caption" class="muted">{{ reading.caption }}</p><div v-if="imageSet.length>1" class="image-controls"><button type="button" @click="changeImage(-1)">上一张</button><span>{{ imageIndex+1 }} / {{ imageSet.length }}</span><button type="button" @click="changeImage(1)">下一张</button></div><div v-if="(reading.media || reading.images)?.length" class="reader-grid"><button v-for="(m,i) in reading.media || reading.images" :key="i" type="button" @click="openImage(m,reading.title,reading.media || reading.images,i)"><img :src="m.url" :alt="m.caption||reading.title" /></button></div></div></dialog>
    </template>
  </main>
</template>
<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {api} from '../api';
const route=useRoute(),router=useRouter(),race=ref(null),archive=ref(null),related=ref([]),loading=ref(true),error=ref(''),heroFailed=ref(false),reader=ref(null),reading=ref(null);
const imageSet=ref([]),imageIndex=ref(0);
const tabs=[{id:'overview',label:'概况'},{id:'entry',label:'参赛'},{id:'route',label:'赛道'},{id:'results',label:'成绩'},{id:'gallery',label:'图鉴'},{id:'updates',label:'动态'}];
const entryTypes=[{id:'registration',label:'报名中签'},{id:'guide',label:'参赛指南'}],galleryTypes=[{id:'参赛服',label:'参赛服',mark:'01'},{id:'奖牌',label:'奖牌',mark:'02'},{id:'参赛包',label:'参赛包',mark:'03'},{id:'完赛包',label:'完赛包',mark:'04'},{id:'albums',label:'官方图集',mark:'05'}];
const legacy={registration:'entry',logistics:'entry',participation:'results',gear:'gallery',stories:'updates'};
const normalized=value=>tabs.some(t=>t.id===value)?value:legacy[value]||'overview';
const tab=ref(normalized(route.query.tab)),gallery=ref('参赛服'),entryType=ref(route.query.tab==='logistics'?'guide':'registration'),updatesType=ref('stories'),entryYear=ref(''),routeYear=ref(''),resultsYear=ref('');let sequence=0;
const editions=computed(()=>[...(archive.value?.editions||[])].sort((a,b)=>Number(b.year)-Number(a.year))),years=computed(()=>editions.value.map(e=>String(e.year))),latest=computed(()=>editions.value[0]);
const foundingYear=computed(()=>archive.value?.profile?.foundingYear || String(archive.value?.intro||'').match(/(?:创办于|始于)(\d{4})|(?:于)?(\d{4})年创办/)?.slice(1).find(Boolean)||'—');
const routeVersions=computed(()=>{const groups=archive.value?.routeGroups?.length?archive.value.routeGroups:(race.value?.id==='beijing'?[{id:'near-2025-2026',title:'2025—2026 · 奥体方向',years:['2026','2025'],match:'similar',note:'公开道路序列相近，各年细部线位分别记录。'}]:[]);const used=new Set();const result=groups.map(g=>({...g,years:(g.years||[]).map(String).filter(y=>years.value.includes(y))})).filter(g=>g.years.length).map(g=>{g.years.forEach(y=>used.add(y));return {...g,route:editions.value.find(e=>String(e.year)===g.years[0])?.route};});return [...result,...editions.value.filter(e=>!used.has(String(e.year))).map(e=>({id:String(e.year),title:e.route?.versionTitle||e.year+' 年路线',years:[String(e.year)],route:e.route}))];});
const activeRouteGroup=computed(()=>routeVersions.value.find(g=>g.years.includes(routeYear.value)));
const selected=y=>editions.value.find(e=>String(e.year)===y),currentEntry=computed(()=>selected(entryYear.value)),routeEdition=computed(()=>selected(routeYear.value)),resultEdition=computed(()=>selected(resultsYear.value));
const heroUrl=computed(()=>!heroFailed.value&&archive.value?.hero?.imageUrl?archive.value.hero.imageUrl:import.meta.env.BASE_URL+(race.value?.id==='beijing'?'images/race-archive-art/beijing-cover.svg':'images/race-landmarks/'+race.value?.id+'.svg'));
const directoryTo=computed(()=>({path:'/race-catalog',query:Object.fromEntries(['q','wa','caa'].filter(k=>route.query[k]).map(k=>[k,route.query[k]]))})),fromRace=computed(()=>related.value.find(r=>String(r.id)===String(route.query.fromRaceId||'')));
const routeStages=computed(()=>String(routeEdition.value?.route?.summary||'').split('→').map(s=>s.trim()).filter(Boolean));
const registrationFields=[['fee','报名费用'],['qualification','报名资格'],['applicants','报名人数'],['eligibleApplicants','有效报名'],['lotteryPool','抽签池人数'],['drawQuota','抽签名额'],['lotteryRate','公布中签率'],['directQuota','直通名额']],participationFields=[['planned','计划规模'],['starters','实际起跑'],['finishers','完赛人数'],['finishRate','完赛率']];
const facts=(obj,fields)=>fields.filter(([key])=>obj?.[key]).map(([key,label])=>({label,value:obj[key]}));
const guideGroups=computed(()=>[{title:'领物安排',fields:facts(currentEntry.value?.logistics?.collection,[['time','领物时间'],['place','领物地点'],['requirements','领取要求']])},{title:'交通与离场',fields:facts(currentEntry.value?.logistics?.transport,[['expo','领物交通'],['start','前往起点'],['finish','终点离场']])},{title:'比赛日服务',fields:facts(currentEntry.value?.logistics?.raceDay,[['startTime','发枪与分区'],['timeLimit','关门安排'],['bagDrop','存取包'],['aidStations','补给与饮水'],['toilets','卫生间'],['medical','医疗服务']])}].filter(x=>x.fields.length));
const galleryEntries=computed(()=>editions.value.flatMap(e=>(e.gear||[]).filter(g=>g.category===gallery.value).map(g=>({year:e.year,gear:g,images:(g.images?.length?g.images:g.imageUrl?[{url:g.imageUrl}]:[]).filter(x=>x.url)}))));
const albums=computed(()=>[...(archive.value?.photoAlbums||[])].sort((a,b)=>Number(b.year)-Number(a.year))),stories=computed(()=>archive.value?.updates?.length?archive.value.updates:archive.value?.stories||[]),news=computed(()=>[...(archive.value?.news||[])].sort((a,b)=>String(b.publishedAt||'').localeCompare(String(a.publishedAt||''))));
function certification(x){return x.label+(x.year?' · '+x.year:'');}function setTab(value){tab.value=value;router.replace({query:{...route.query,tab:value}});}function openReader(item){imageSet.value=[];reading.value=item;reader.value?.showModal();}function closeReader(){reader.value?.close();}function openImage(item,title,images=[item],index=0){imageSet.value=images;imageIndex.value=index;reading.value={title,image:item.url,caption:item.caption};if(!reader.value?.open)reader.value?.showModal();}function changeImage(delta){if(!imageSet.value.length)return;imageIndex.value=(imageIndex.value+delta+imageSet.value.length)%imageSet.value.length;const img=imageSet.value[imageIndex.value];reading.value={...reading.value,image:img.url,caption:img.caption};}function openAlbum(item){imageSet.value=[];reading.value={title:item.title,media:item.media};reader.value?.showModal();}
async function load(){const ticket=++sequence;loading.value=true;error.value='';heroFailed.value=false;try{const d=await api('/race-catalog/'+encodeURIComponent(String(route.params.id)));if(ticket!==sequence)return;race.value=d.race;archive.value=d.archive;related.value=d.relatedRaces||[];const linked=String(related.value.find(r=>String(r.id)===String(route.query.fromRaceId||''))?.raceDate||'').slice(0,4);const requested=String(route.query.year||linked),initial=years.value.includes(requested)?requested:String(d.defaultYear||d.latestYear||years.value[0]||'');entryYear.value=initial;routeYear.value=initial;resultsYear.value=years.value.includes(requested)?requested:String(editions.value.find(e=>e.results?.length)?.year||initial);}catch(e){if(ticket===sequence)error.value=e.message||'赛事档案暂时无法加载';}finally{if(ticket===sequence)loading.value=false;}}
watch(()=>route.params.id,load,{immediate:true});watch(()=>route.query.tab,v=>{tab.value=normalized(v);});onBeforeUnmount(()=>sequence++);
</script>
<style scoped src="../race-archive-category.css"></style>
